    "G26_32": {
      "title": "▲閱讀材料，回答第 26–32 題",
      "passage": "<p>文意，選出一個最適合該空格的答案。</p><p>People first started using money in order to trade. A farmer who had cattle might want to use<br> 26 to preserve meat or cloth to make clothing. For this farmer, a cow became a “medium of<br> 27 ” — a way of getting things that the farmer did not make or grow. Cattle thus became a form of<br>money. 28, whatever people agreed to trade became the earliest kinds of money.<br> By the time of the Middle Ages in Europe (about A.D. 800-1100), gold 29 a popular medium<br>for trade. But gold was heavy and difficult to carry, and it was very dangerous to travel with large<br> 30 of gold in Europe at that time. 31 merchants and goldsmiths began issuing notes<br>promising to pay gold to the person who carried the note. These “promissory notes” were the 32<br>of paper money in Europe.</p>"
    },
