  "groups": {
    "G26_33": {
      "title": "▲閱讀材料，回答第 26–33 題",
      "passage": "<p>共 8 頁 第 4 頁</p><p>IV、綜合測驗：下面兩篇短文，共有 15 個空格，為第 26 – 40 題，每題有四個選項，請依文<br> 意選出一個最適合該空格的答案。</p><p>If we need to generalize about the life of old people in Taiwan, we can say that they lead a lonely<br>life. Many of them live alone because they are 26 widowed or divorced. A deep sense of<br>separation 27 others and thereby a sense of isolation make them very 28. Under these<br>circumstances, they feel that they are living in a hostile environment 29 others pay little attention<br>to them. 30, old people can reestablish their role in society 31 taking part in community<br>activities and 32 friends with others. If they are willing to try, they will 33 feel isolated.</p>"
    },
    "G34_40": {
      "title": "▲閱讀材料，回答第 34–40 題",
      "passage": "<p>People around the world are crazy about Harry Potter series. The main character, Harry Potter,<br>is loved throughout the world, and 34 is his creator. J. K. Rowling is a true wizard, a woman<br>35 provides readers with a fantastic world. Divorced, Rowling 36 public assistance in a tiny<br>flat with her infant daughter. At that time, she had to 37 all the time, so she wrote Harry Potter<br>and the Sorcerer’s Stone at a table in a café during her daughter’s naps. Rowling creates a child who<br>escapes 38 the confines of the adult world and goes somewhere he has power. After Rowling<br>began writing about Harry and his friends, she felt that 39 what situation she found herself in, she<br>could always turn to the character she had created. 40 was Harry Potter that rescued her. Harry<br>Potter series is really about the power of imagination. What Harry is learning to do is to develop his full<br>potential.</p>",
      "image": "img/91/pages/page-05.png"
    },
    "G41_45": {
      "title": "▲閱讀材料，回答第 41–45 題",
      "passage": "<p>第 5 頁 共 8 頁</p><p>V、閱讀測驗：下面有兩篇短文，其後共有 10 個題目，為第 41 – 50 題，請閱讀短文後，選出<br> 一個最適當的答案。</p><p>Mike has had a bad cold and a sore throat for three days. This morning, he had a high fever and<br>a running nose, so his mother took him to the doctor. Here are the directions of the medicine that Dr.<br>Wang has prescribed for Mike.</p><p>DOSAGE: Adults and children 12 years of age and older take 2 spoonfuls of this medical liquid<br>every 6 hours. Do not take more than twelve spoonfuls in 24 hours. Children 6 years old to 12 years<br>old take half of the adult dosage, not more than 6 spoonfuls per day. Do not use this product in children<br>under 6 years of age. This will provide overdose and could cause serious health problem.</p><p>WARNING: Do not take the medicine any more than the suggested dosage unless directed by a<br>doctor. Keep the medicine away from the reach of children under six years old. Patients with high<br>blood pressure, heart disease or stomach trouble are forbidden to take this medicine. This medicine may<br>cause sleepiness. Do not drive or operate any machine while taking this medicine. Chronic cough,<br>which usually lasts a long time, is dangerous and harmful. If your cough continues for three days,<br>discontinue use and ask your doctor for advice.</p>"
    },
    "G46_50": {
      "title": "▲閱讀材料，回答第 46–50 題",
      "passage": "<p>Euthanasia（安樂死）is the practice of ending the life of a person who is hopelessly ill. It is<br>commonly called mercy killing or painless death. It is an issue causing heated debate.</p><p>Many people are opposed to euthanasia for four reasons. First, they argue that no matter how<br>you look at it, euthanasia is killing or suicide and thus is wrong and immoral. The second reason is that<br>there is always the possibility of a wrong diagnosis. Doctors are not flawless, and even the best of them<br>makes mistakes. In addition, there is always the chance that some new pain-killing medicine or even a<br>cure is just around the corner. The most important reason to oppose euthanasia, for many, is the risk of<br>abuse. They are afraid that criminals or bad people may use euthanasia to serve their evil purposes.</p><p>However, there is the other side of the issue. A large number of people support euthanasia.<br>One common argument for euthanasia is that patients with incurable diseases should not be forced to<br>continue living if they are in great pain and cannot bear this constantly. The second reason is that<br>staying in a hospital for a long time often causes a financial and emotional burden on the family.<br>Incurably ill patients often worry about the hardship and misery that will fall on their families.<br>Moreover, incurable patients often find their lives meaningless. Even if they are alive, they can only lie<br>in bed. For many, this is living death, and they would rather choose to die with dignity. Finally,<br>proponents believe that keeping dying patients alive on life-support systems is cruel and senseless, for it<br>causes great suffering to both the patients and their families, and places great burdens on the community.<br>Therefore, supporters believe, doctors should have the right to end the life of a terminally ill patient with<br>the permission of the patient or the family.</p>"
    }
  },
