      "passage": "<p>短文之文意，選出一個最適合該空格的答案。</p><p>One day the manager of the Grand Hotel in Taipei was called upon to deal with the complaint of<br>a young lady. “I can’t 26 the noise another minute,” she told the manager 27.<br>“You must tell the man across the hall to stop 28 the horrible noise.” And, seeing the<br>look of surprise on the manager’s face, she added, “If you don’t make him stop, I’ll check out at<br>once.”<br> “I’m very sorry it’s disturbing you,” the manager said patiently. “That’s Yo-Yo Ma (馬友友).”<br>It was the lady’s turn to look surprised. “What?” she said, much 29. “The great<br>musician Yo-Yo Ma?” She was silent for a moment. “Well, of course, that’s different. Please<br>don’t say a word to him.”<br> Two days later, the manager happened to hear her talking to another visitor in the lobby. “It’s<br>so 30,” she was saying, “I can open my door every morning and hear Yo-Yo Ma<br>practice.”</p>"
