      "passage": "<p>The effect of physical and mental demands and pressures on the human body may be thought<br>of as stress. Everyone’s life has some stress. In day-to-day situations, your body can handle<br>normal stress. Even when stress continues, the body will react by demanding physical and mental<br>rest. After rest, it is again ready to take on stress.<br> In fact, a certain amount of stress is necessary. The right amount for you depends on your<br>individual physical and mental makeup. Alicia, for example, is always on the go. She joins in<br>all sorts of clubs and organizations in school. Out of school, she competes year-round in sailing<br>races. Keeping up with all her activities requires her to handle a great deal of physical and mental<br>stress.</p>"
