  "groups": {
    "G26_33": {
      "title": "▲閱讀材料，回答第 26–33 題",
      "passage": "<p>共 8 頁 第 4 頁</p><p>III. 綜合測驗：以下兩篇短文共有 15 個空格，為第 26 – 40 題，每題有四個選項，<br> 請依各篇短文文意，選出一個最適合該空格的答案。</p><p>Job hunters need many skills. They need to know where to look for a job, and they need to be<br>able to write clear, complete information about themselves in letters of application. 26, they<br>need to know how to transfer this information on to a job application form. Furthermore, they need<br>to know 27 to get information about a job over the telephone. And 28, job seekers must<br>know the techniques of a job interview.<br> First, where to find a job? Jobs can be found in the daily newspaper, in the 29 advertisement<br>section, as well as on the Internet. Many find jobs by networking – that is, they let their friends and<br>relatives know that they are looking for a job. Networking is increasingly popular, and, 30, it<br>often works.<br> Once a possible job has been found, what should job hunters do? First, they must learn all<br>about the job and ask themselves these questions: Am I qualified for this job? Do I want this job?<br>Is it challenging? Is it interesting? Does it pay well? If all 31 are answered positively, then the<br>next step the applicants need to do is to apply for the job. Nearly every job 32 some forms of<br>written application. Most job application forms ask for similar information about 33 data,<br>including educational background, employment history, and references.</p>",
      "image": "img/94/pages/page-05.png"
    },
    "G34_40": {
      "title": "▲閱讀材料，回答第 34–40 題",
      "passage": "<p>Since the invention of the Internet, many people have predicted a paperless society. This<br> 34 has come to reality as people use the Internet to read newspapers, send and receive e-mails,<br>and access information. 35, here are others who doubt that computer technology will ever lead<br>to a paperless society.</p>"
    },
    "G41_45": {
      "title": "▲閱讀材料，回答第 41–45 題",
      "passage": "<p>短文後，選出最適當的答案。<br> Nature is full of examples of cycles. The seasons come and go in a cycle of spring, summer,<br>autumn, and winter. The days move in cycles of day and night. And all living things live, grow, and<br>die in cycles. For example, a sapling grows tall and strong. Then, one spring, the tree blossoms.<br>These flowers later turn into fruit or other types of seeds. When these seeds fall, they land on the<br>ground. The seeds can then grow. If the seeds get enough sunlight and rain, they will become young<br>trees. As the trees blossom, the cycle repeats itself.<br> Rain also occurs in cycles. Water evaporates from the oceans and rises into the sky. This<br>means that the ocean water is warmed by the sun and some of it rises into the air. When enough<br>water has gathered together, big rain clouds form. The clouds will release or drop the water. The<br>rain falls on land and ocean alike. When the rain falls on land, the ground soaks up some of it. If a<br>lot of rain falls, the runoff flows into streams, rivers, and lakes. This water, in turn, flows into the<br>oceans. When some of this water evaporates into the air, the cycle repeats itself.</p>"
    },
    "G46_50": {
      "title": "▲閱讀材料，回答第 46–50 題",
      "passage": "<p>A strong, healthy body can do an amazing job of resisting disease. There are many things you<br>can do to keep your body healthy. Eating proper foods is one of the effective ways. A balanced diet<br>gives the body the nutrients it needs to function properly.<br> Getting plenty of sleep is another good way. A tired, run-down body does not function<br>efficiently and is like a car that needs a tune-up. Sleep refreshes the body and restores the energy<br>necessary to fight disease.<br> Exercise is also important in reducing stress and keeping the body healthy. Regular, moderate<br>exercise, such as running, dancing, swimming, biking or playing a sport, will relieve muscle tension,<br>keep the muscles firm, and make the heart and blood vessels healthy. Exercise, like sleep, makes the<br>body function more efficiently. People who exercise regularly can even strengthen their hearts.</p>"
    }
  },
