      "passage": "<p>Panda babies are weak and need tremendous care. 26 pandas are born, they are very small<br>and delicate. Their average 27 at birth is only about 90 grams. Panda babies are actually<br>smaller than a mouse. They cannot see or walk. 28 they receive close attention, panda babies<br>die easily. According to a recent medical study, 61 percent of the pandas that are born in zoos die<br> 29 after birth. The number could be 30 if we did nothing. In China, and in zoos all over<br>the world, people are trying to help pandas have healthy babies. The 31 is that the panda is an<br>endangered species. There are almost no pandas left in the 32. However, we are getting better</p>"
