      "passage": "<p>My parents are an interesting couple. They don’t mean to 34 each other but what they do<br>is humorous.<br> When my dad was thirty something, he hit himself on the forehead very hard on something<br>inside the garage. So, my mother 35 him to an emergency room. Because my father cut<br>himself very badly, the doctor had to perform a 36. Seeing my father suffering, my mother felt<br>weak; the nurse pulled a chair up for her and then went back to dad’s side. “I know we’re all<br>grown-ups,” said the nurse, “but, it’s OK to cry sometimes when it hurts.” After the operation was<br>done, my mother asked my father 37 he heard what the nurse said or not. “I did,” my father<br>replied, “and I thought she was talking to you.”<br> Days after staying in the hospital, my father could finally go home. 38 the way home, my<br>mother asked my father what the most uncomfortable thing he had during his stay. “The food, of<br>course.” My mother looked at my father with a smile, 39 what she was going to fix for him.<br> 40, my father continued, in a very philosophical tone, “If I have to eat that kind of food, why<br>do I have to stay in the hospital? ” That evening, we had McDonald’s.</p>",
