    "G41_45": {
      "title": "▲閱讀材料，回答第 41–45 題",
      "passage": "<p>第 5 頁 共 8 頁</p><p>IV. 閱讀測驗：下面兩篇短文，每篇各有 5 題，為第 41-50 題，請閱讀短文後，<br> 選出最適當的答案。</p><p>Music is a powerful thing. When played properly, some music can have positive effects on<br>learning and attitude. One way that music can make learning easier is by teaching people abstract<br>reasoning and learning strategies. When learning music, people visualize the task in their head, and<br>therefore exercise the same abstract skills that engineers, chess players, and high-level<br>mathematicians use. Moreover, instruction in music skills and appreciation provides a wealth of<br>learning strategies that help to develop children’s analyzing, synthesizing, and evaluating skills.<br>Another important aspect that music can have on learning for people of all ages is attitude. The<br>highly repetitive structure of music helps children learn to trust themselves and enhance their<br>self-confidence and sense of accomplishment. Thus, their attitude toward learning is dramatically<br>increased. In addition to increasing positive attitude, listening to pleasant music in the background<br>may ease the strain of an activity. Notice that when people listen to music in the background, it is<br>very important that they listen to the music they are familiar and comfortable with. So in order for<br>music to help us think, learn, and work, we need to know what kind of music to listen to.</p>",
      "image": "img/95/pages/page-06.png"
    },
    "G46_50": {
      "title": "▲閱讀材料，回答第 46–50 題",
      "passage": "<p>共 8 頁 第 6 頁</p><p>People have always searched the sky for clues about upcoming weather. Throughout the ages,<br>farmers and sailors have looked to the winds and clouds for signs of approaching storms. But no<br>real understanding of the weather could be achieved without a scientific study of the atmosphere.<br>Such a study depends on being able to measure certain conditions, including pressure, temperature,<br>and moisture levels.<br> A true scientific examination of weather, therefore, was not possible until the development of<br>accurate measuring instruments, beginning in the 17th century. Meteorology — the science of<br>studying the atmosphere — was born in 1643 with the invention of the barometer, which measures<br>atmospheric pressure. The liquid-in-glass thermometer, the hydrometer to measure humidity — the<br>amount of moisture in the air — and the weather map also were invented during the 1600s.<br> With the measurement of these basic elements, scientists began to work out the relationships<br>between these and other atmospheric conditions, such as wind, clouds, and rainfall. Still, their<br>observations failed to show an overall picture of the weather. Such complete weather reporting had<br>to wait two centuries for the rapid transfer of information made possible by the invention of the<br>telegraph during the 1840s.</p>",
      "image": "img/95/pages/page-07.png"
    }
