      "passage": "<p>的答案。</p><p>Vincent Willem van Gogh (30 March, 1853 – 29 July, 1890) was a Dutch Post-<br> Impressionist painter whose work had a far-reaching influence on 20th century art. Little<br> 31 during his lifetime, his fame grew in the years after his death. Today, he is widely<br> regarded as one of history’s greatest painters and an important 32 to the foundations of<br> modern art. Van Gogh did not begin painting 33 his late twenties, and most of his best-<br> known works were produced during his final two years. He produced more than 2,000 artworks,<br> 34 of around 900 paintings and 1,100 drawings and sketches. He was little known during<br> his lifetime; however, his work was a strong influence on the Modernist art 35, and today<br> many of his pieces — including his numerous self portraits, landscapes, portraits and<br> sunflowers — are among the world’s most recognizable and expensive works of art.</p>"
