  "groups": {
    "G26_30": {
      "title": "▲閱讀材料，回答第 26–30 題",
      "passage": "<p>的答案。</p><p>CouchSurfing has developed into a new craze for the travel community since it began in 1999.<br>CouchSurfing, usually 26 as CS, offers a great way for budget conscious travelers to travel the<br>world in a far less expensive way. CS works when travelers find people who are willing to open up their<br>homes to them and have spare couches for them to sleep on. 27 saving money on accommodation,<br>CS provides travelers 28 a unique opportunity to encounter local perspectives from the area in<br>which they are traveling, 29 various cultural, political, and religious viewpoints and lifestyles. Do<br>you have a limited travel budget? Are you comfortable spending time with strangers? Do you want to<br>experience different outlooks from other parts of the world? 30 CouchSurfing.org, a popular social<br>networking site for both surfers and hosts, to gain a better understanding of how to find and contact<br>potential hosts and begin your journey today. You won’t be disappointed.</p>",
      "image": "img/101/pages/page-04.png"
    },
    "G31_35": {
      "title": "▲閱讀材料，回答第 31–35 題",
      "passage": "<p>共8頁 第4頁</p><p>公告試題僅供參考 共同科目 英文</p><p>▲ 下篇短文共有 5 個空格，為第 31 – 35 題，請依短文文意，選出一個最適合該空格<br> 的答案。</p><p>A few interesting similarities can be found between the two great philosophers: Confucius and<br>Socrates. They indicated that virtue can cause happiness in life. Using their own lives as 31, they<br>tried to tell their followers that acting virtuously is the way to success in life. Another common point<br>between Confucius and Socrates is their emphasis on the importance of education. 32 education, it<br>is difficult to build up the virtue of wisdom. They considered self-knowledge important. Self-knowledge<br>refers to the ability to know what we know and what we do not know. With the awareness of our own<br>knowledge and 33, we are able to succeed and avoid errors. They believed that careful<br>self-examination can analyze and 34 our personal characters, aims, methods and attitudes. For<br>both Confucius and Socrates, 35 learning and wisdom with other virtues, one can have a good<br>and productive life. They pointed out that wisdom obtained from learning can be used as guidance for<br>all good deeds.</p>"
    },
    "G36_40": {
      "title": "▲閱讀材料，回答第 36–40 題",
      "passage": "<p>的答案。</p><p>A computer addict uses a computer all the time — playing online games, browsing websites,<br>e-mailing friends, and so on. He is annoyed when he has no 36 to the computer. As soon as he<br>turns it on, he feels 37 again. Computer addiction is a social and physical problem. Socially, a<br>person with a computer addiction thinks his “Cyber friends” are important, so he spends less time<br>with his family and friends. Physically, a computer addict can 38 symptoms such as dry eyes,<br>headaches, and backaches after he hasn’t eaten and slept properly for some time. If you are a<br>computer addict, you need to help yourself. First, 39 that you have a problem. Then, talk to<br>your family about it and limit your computer use. For example, 40 an alarm clock before using<br>a computer. Turn the computer off when the clock rings. Take action now, or the computer will take<br>a full control of you.</p>"
    },
    "G41_45": {
      "title": "▲閱讀材料，回答第 41–45 題",
      "passage": "<p>第5頁 共8頁</p><p>IV. 閱讀測驗：以下有兩篇短文，共有 10 個題目，為第 41 至 50 題，請於閱讀<br> 短文後，選出最適當的答案。</p><p>▲ 閱讀下文，回答第 41 − 45 題</p><p>For those who think of straws as nothing but animal feed, materials for the roof, natural fertilizers<br>or occasional medical herbs, I would suggest that they take a trip to Snugburys. Snugburys, an<br>ice cream maker in the U.K., has had a plan to construct a sculpture every year in their farm field<br>to celebrate the coming of summer. This year, they have a GIANT polar bear — a statue which has<br>3 tons of straws inside. The steel-skeleton-straw-stuffed replica of the animal from the arctic region<br>is attracting interest from tourists, visitors or ice cream buyers while keeping guard at this ice cream<br>destination beside A51 Chester Road. The animal is approximately four times as big as a real adult<br>male polar bear: standing 38 feet tall and weighing in at 9 tons. The sculpture will stay there for<br>about half a year. “Ex-straw-dinary!” uttered one of my friends. The concept started in 1998 with a<br>huge Millennium Dome sculpture and, since then, on the list of the works of art are replicas of the<br>Big Ben Clock, a windmill, the Lovell telescope, a rocket, an angel from the West, a dinosaur as<br>well as last year’s meerkat. Speaking about this year’s design, Mr. Sadler, the business owner,<br>responded with a smile: “There’s no real reason why we chose a polar bear but we think that they’re<br>cool and ice cream is cool so I guess that’s a good enough explanation!” A certain part of all sales<br>from the shop’s “Polar Bear Cones” will be given away to The Children’s Adventure Farm Trust<br>which provides holidays for the kids in need: ill at a terminal stage, disabled, disadvantaged and the<br>like.</p>"
    },
    "G46_50": {
      "title": "▲閱讀材料，回答第 46–50 題",
      "passage": "<p>共8頁 第6頁</p><p>公告試題僅供參考 共同科目 英文</p><p>▲ 閱讀下文，回答第 46 − 50 題</p><p>Michael Hart, founder of Project Gutenberg, invented eBooks in 1971 and continued to inspire<br>the creation of eBooks and related technologies today. He announced that the greatest value created by<br>computers would not be computing, but the storage, retrieval and searching of what was stored in our<br>libraries. There are three categories of the Project Gutenberg Library: Light Literature — such as<br>Alice in Wonderland, Through the Looking-Glass, A Christmas Carol, Peter Pan, Aesop’s Fables, etc;<br>Heavy Literature — such as the Bible or other religious documents, Shakespeare, Moby Dick,<br>Paradise Lost, Heart of Darkness, etc; References — such as Roget’s Thesaurus, almanacs,<br>dictionaries, encyclopedias, etc. The Light Literature Collection is designed to get people to the<br>computer in the first place, whether a preschooler or a great-grandparent. We (Project Gutenberg team)<br>love to hear about kids or grandparents taking each other to an Etext to Peter Pan when they come back<br>from watching HOOK at the movies, or when they read Alice in Wonderland after seeing it on TV.<br>Nearly every Star Trek movie has quoted current Project Gutenberg Etext releases. This was a<br>primary concern when we chose the books for our libraries.</p>"
    }
  },
