    "G41_45": {
      "title": "▲閱讀材料，回答第 41–45 題",
      "passage": "<p>第 5頁 共 8頁</p><p>IV. 閱讀測驗：以下有兩篇短文，共有 10 個題目，為第 41 至 50 題，請於閱讀<br> 短文後選出最適當的答案。<br>▲ 閱讀下文，回答第 41 – 45 題<br> Have you ever skipped sleeping over a video game? Computer game designers often<br> create interesting video games to tempt players to keep playing. These days, many employees<br> are found to play video games at work even though their employers have set rules to stop them<br> from doing so. In fact, video game addiction is regarded as harmful, just like addiction to<br> drugs, alcohol, or gambling, and should be treated with care.<br> In the workplace, addicted players are often seen as lazy, not sick; their bosses are not<br> sympathetic to their addiction. If they have been caught several times playing video games<br> at work, their salary may be cut, and even worse, they may lose their jobs. In some companies,<br> the addicted players are allowed to play video games only on stressful days, but their bosses<br> will check their computers from time to time to make sure that they are doing their work.<br> However, while some companies continue to find some methods of preventing workday playing,<br> addicted players still have their own ways to enjoy playing video games during working<br> hours.</p>"
    },
    "G46_50": {
      "title": "▲閱讀材料，回答第 46–50 題",
      "passage": "<p>共 8頁 第 6頁</p><p>公告試題僅供參考 共同科目 英文</p><p>▲ 閱讀下文，回答第 46 – 50 題<br> A new food bank was just opened recently in Taichung. People in financial difficulties can<br> go there to pick up relief products, and like going to a supermarket, they can get what they<br> need, free of charge and with dignity. In all food banks, items are donated by businesses, with a<br> small number of products, such as diapers and vitamins, purchased with subsidies from the city<br> government. One important goal of the food banks is to reduce the waste of resources while<br> giving away food and other daily necessities to those in need. Most food banks often hand out<br> food packs without giving recipients a choice of the items. In that way, products still go to waste<br> if the recipients are unable to use them. Moreover, the food packs do not contain milk powder or<br> diapers to meet the needs of infants. However, at the new supermarket-like food bank, recipients<br> can choose what they want and what they need from a wide range of products, which include<br> diapers, infant formula milk powder, and children’s shoes.<br> In addition, the new food bank holds activities similar to those in other food banks.<br> For instance, volunteers plan special holiday surprises for recipients and give away festive foods<br> such as mooncakes. The main beneficiaries of food banks are the people who need a helping<br> hand to avoid extreme poverty. Regardless of how they work, all food banks share the same<br> goal: to lift disadvantaged families out of poverty.</p>"
    }
