      "passage": "<p>空格的答案。<br> Jacky is the most interesting person in our office because he is kind but curious and slow.<br> He never tries to take 22 of his colleagues; instead, he is very generous. Whenever we are<br> in need of assistance, he always tries to give us a 23. Nevertheless, he likes to inquire into<br> other’s business 24 has nothing to do with him. Not only is he interested in how anyone<br> of us does his or her work, 25 he is also interested in our personal matters. Moreover, he<br> usually works in such a slow manner that most of us get impatient with him. Naturally, a lot of<br> work is delayed simply 26 his slowness. Despite his weaknesses, we still appreciate his<br> helpfulness.</p>"
