  "groups": {
    "G22_26": {
      "title": "▲閱讀材料，回答第 22–26 題",
      "passage": "<p>空格的答案。<br> Have you ever imagined that you can chat with a robot instead of a real person? The<br> techniques of Artificial Intelligence (AI) 22 become mature. Many companies, such as<br> Google, Amazon, and Apple, have created smart voice assistants that can understand what you<br> say, search for answers to your questions, and complete some tasks 23 on your instructions.<br> More recently, chatbots, which are computer programs with AI techniques on apps, have been<br> developed in order to present useful information whenever users request 24. From the<br> perspectives of business, replacing humans 25 chatbots can save money. As a result, many<br> companies nowadays want to develop their own chatbots. Therefore, people might lose their<br> jobs due to the 26 of chatbots. At the same time, many new companies which build<br> chatbots have sprung up, and this will create many new job opportunities.</p>"
    },
    "G27_31": {
      "title": "▲閱讀材料，回答第 27–31 題",
      "passage": "<p>108 年四技<br>英文 共同科目 公告試題僅供參考 第 5頁</p><p>▲ 下篇短文共有 5 個空格，為第 27 － 31 題，請依短文文意，選出一個最適合該<br> 空格的答案。<br> Many people celebrate their birthdays with a cake and candles. But, have you ever<br> wondered how the birthday celebration started? According to some historians, putting<br> candles on the cake 27 in Ancient Greece. The Greeks would make moon-shaped cakes to<br> honor Artemis, the goddess of the moon. On top of the cake 28 lit candles representing the<br> glow of the moon. The smoke from the candles was believed to serve the dual purpose of<br> preventing 29 evil spirits, and carrying prayers and wishes to the heavens. Today, birthday<br> cakes with lit candles on top have become a popular way of birthday celebration. The number of<br> candles usually represents the age of the person 30 celebrated. He or she will make wishes<br> including a silent one and then 31 all the candles in one breath. As a modern tradition, the<br> silent wish would not be told to anyone else, or it would never be realized.</p>"
    },
    "G32_36": {
      "title": "▲閱讀材料，回答第 32–36 題",
      "passage": "<p>共 8頁 公告試題僅供參考 108 年四技</p><p>Ⅳ. 閱讀測驗：以下有兩篇短文，共有 10 個題目，為第 32 至 41 題，請於閱讀短文後，<br> 選出最適當的答案。<br>▲ 閱讀下文，回答第 32 －36 題<br> Water pollution is a serious problem in the United States. Unsafe levels of toxic chemicals<br> linked to cancer have been found in the drinking water of 33 states. To solve this problem, Eric Li,<br> the founder and CEO of Ecomo, has developed the world’s first smart water bottle.<br> It took Li about two years to develop the water bottle that is very easy to use. After filling<br> water from a tap, lake, or even toilet, all you need to do is shake, twist, and drink. In less than<br> five seconds, the filter, the bottle’s water-cleaning mechanism, removes 99 percent of bacteria,<br> pesticides, petroleum products, and heavy metals. If the water is clean, the word “Good” appears<br> on the LED monitor with a green light flashing. If it is still undrinkable, a yellow or red light<br> and the word “Fail” or “Bad” will appear on the monitor at the same time.<br> Ecomo, which is the name of the bottle and is short for “eco-monitor,” has other features<br> that consumers will enjoy. The bottle weighs just 0.37 kilograms, but it can store almost 600<br> milliliters of water. Furthermore, it can keep water hot for 12 hours or cold for 24 hours.<br> Customers are warned, however, not to fill the bottle with other kinds of liquids because these<br> will damage the bottle.<br> Two other notable aspects of the product are the app and Bluetooth wristband that the<br> product works with. The app sends a notice to users when it is time to change the filter. In<br> addition to measuring temperature, the Bluetooth wristband records users’ daily activities,<br> calculates their water needs, and monitors their water intake.</p>",
      "image": "img/108/pages/page-06.png"
    },
    "G37_41": {
      "title": "▲閱讀材料，回答第 37–41 題",
      "passage": "<p>108 年四技<br>英文 共同科目 公告試題僅供參考 第 7頁</p><p>▲ 閱讀下文，回答第 37 －41 題<br> With summer vacation right around the corner, many people are planning to travel abroad.<br> Some of them take an overseas trip with their friends and family while others join package tours<br> to visit foreign countries. Nowadays, many young people prefer a backpacking trip abroad.<br> Since backpacking is a new form of tourism and getting more popular among young people,<br> experienced travelers have some suggestions for those would-be backpackers.<br> First, plan your budget and prepare the required travel documents. You need to figure out in<br> advance how much your trip may cost you. Remember to check with banks and find out the usage<br> of ATM cards and the exchange rate so that you have enough money before the trip. Then, make<br> sure to have travel documents such as a passport and visa on hand. It is also good to leave a copy<br> of these documents to a family member whom you can contact in case of emergency.<br> Second, choose accommodation that is close to public transportation. In Taiwan, for<br> example, backpackers can easily travel by using such public transportation systems as trains,<br> buses, the High Speed Rail, and the Mass Rapid Transit in major cities. With convenient<br> transportation, backpackers can save their time and energy to move from nearby stations to<br> hotels, hostels, or tourist attractions.<br> Third and finally, do not be shy; try to make friends, taste the local food, and visit<br> sightseeing spots when you arrive at a destination. In this manner, your adventures will help you<br> experience more about foreign cultures and lifestyles, thus helping you feel refreshed both<br> physically and spiritually.<br> Go ahead and take on the backpacking challenge. It is certainly a chance for you to prove<br> yourself ready for this new style of tourism.</p>"
    }
  },
