      "passage": "<p>空格的答案。</p><p>Rainforests are the Earth’s oldest living ecosystems. They 22 only a small part of<br> the Earth’s surface, about six percent, but they are very important to us. For example, they<br> provide us with 23 of the Earth’s oxygen and fresh water. A lot of medicines we use today<br> to treat cancer or heart disease 24 from the plants that grow only in rainforests. Many items<br> we use in our own homes come from the rainforest as well. 25, rainforests are disappearing<br> at an alarmingly fast pace, largely due to human development over the past few centuries.<br> Problems 26 from the decrease of rainforests include more pollutions, less oxygen, and<br> fewer species of animals. To keep rainforests from disappearing and save the Earth for our<br> children, we must do something immediately.</p>"
