      "passage": "<p>109 年四技<br>英文 共同科目 公告試題僅供參考 第 5頁</p><p>▲ 下篇短文共有 5 個空格，為第 27 － 31 題，請依短文文意，選出一個最適合該<br>空格的答案。<br> In 1275, Marco Polo (馬可波羅) arrived in China. During this journey, he came close to<br> losing his life a few times, 27 he kept going and finally succeeded in reaching his goal.<br> At about the same time, Polynesians (玻里尼西亞人) were exploring the islands of the South<br> Pacific. 28 the great dangers of sailing long distance in open canoes, they managed to<br> explore and occupy all the major islands. About 200 years later, Christopher Columbus (哥倫布)<br> left Europe to find a new way to Asia. 29 the earth to be flat, many people at that time were<br> afraid that he would fall off the edge of the world. Columbus did not reach his original goal to<br> find treasures in Asia; 30, he opened up a vast new world, the Americas. Every explorer<br> needs a vision. But what 31 explorers to leave the security of the known world to face<br> the dangers of the unknown? For many of them, it is simply the love of adventure.</p>"
