      "passage": "<table><tbody><tr>\n<td></td>\n<td colspan=\"5\">The Diamond Hotel is a\nquarantine hotel. It has seventy rooms for guests. Every room can only\nhave one guest. This line graph shows how many of the rooms were\noccupied during 2020 and 2021.</td>\n</tr></tbody></table>"
