    "G25_28": {
      "title": "▲閱讀材料，回答第 25–28 題",
      "passage": "<table><tbody><tr>\n<td></td>\n<td colspan=\"5\"><p>　　The 3D printer is a\nmachine that can create three-dimensional solid objects. In the printing\nprocess, the printer adds layers upon layers of materials until a solid\nobject is completed. <u>　25　</u>, 3D printers only made small, simple\nplastic objects. But now, 3D printer technology can help house builders\nknow the exact amount of materials they need even before they start\nconstruction. Therefore, building 3D printed homes requires fewer\nresources and produces <u>　26　</u> waste than the traditional way.</p>\n<p>　　The 3D printer can improve the quality of the objects they create\nby using artificial intelligence ( AI ). One of the most exciting\napplications of AI in 3D printing <u>　27　</u> generative design.\nGenerative design is a computer-aided design technique that uses AI to\nimprove the design process. It helps create lighter and stronger\nstructures. This is because AI can find the best way to reduce the\nweight of a structure <u>　28　</u> increasing its strength. In this\nway, better buildings can be created.</p></td>\n</tr></tbody></table>"
    },
