      "passage": "<table><tbody><tr>\n<td></td>\n<td colspan=\"5\"><p>　　Answer the questions based on the following\ntimetable.</p>\n<table>\n<colgroup>\n<col>\n<col>\n<col>\n<col>\n<col>\n<col>\n<col>\n<col>\n<col>\n</colgroup>\n<thead>\n<tr>\n<th colspan=\"9\"><strong>Timetable</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Train No.</strong></td>\n<td><strong>Operation<br>\nDay</strong></td>\n<td><strong>Taichung</strong></td>\n<td><strong>Miaoli</strong></td>\n<td><strong>Hsinchu</strong></td>\n<td><strong>Taoyuan</strong></td>\n<td><strong>Banqiao</strong></td>\n<td><strong>Taipei</strong></td>\n<td><strong>Nangang</strong></td>\n</tr>\n<tr>\n<td><strong>1510</strong></td>\n<td>Mon ~ Fri</td>\n<td>07:12</td>\n<td>07:31</td>\n<td>07:45</td>\n<td>07:58</td>\n<td>08:10</td>\n<td>08:21</td>\n<td>08:30</td>\n</tr>\n<tr>\n<td><strong>802</strong></td>\n<td>Daily</td>\n<td>07:25</td>\n<td>07:45</td>\n<td>07:58</td>\n<td>08:10</td>\n<td>08:22</td>\n<td>08:32</td>\n<td>08:40</td>\n</tr>\n<tr>\n<td><strong>1202</strong></td>\n<td>Mon ~ Fri</td>\n<td>07:21</td>\n<td>—</td>\n<td>—</td>\n<td>—</td>\n<td>—</td>\n<td>08:07</td>\n<td>08:15</td>\n</tr>\n<tr>\n<td><strong>1602</strong></td>\n<td>Mon ~ Fri</td>\n<td>07:40</td>\n<td>—</td>\n<td>08:05</td>\n<td>08:18</td>\n<td>08:31</td>\n<td>08:42</td>\n<td>08:50</td>\n</tr>\n<tr>\n<td><strong>1302</strong></td>\n<td>Mon ~ Fri</td>\n<td>07:53</td>\n<td>—</td>\n<td>—</td>\n<td>08:27</td>\n<td>—</td>\n<td>08:47</td>\n<td>08:55</td>\n</tr>\n<tr>\n<td><strong>204</strong></td>\n<td>Daily</td>\n<td>07:48</td>\n<td>—</td>\n<td>—</td>\n<td>—</td>\n<td>08:27</td>\n<td>08:37</td>\n<td>08:45</td>\n</tr>\n<tr>\n<td><strong>606</strong></td>\n<td>Sat</td>\n<td>08:00</td>\n<td>—</td>\n<td>08:25</td>\n<td>08:38</td>\n<td>08:51</td>\n<td>09:02</td>\n<td>09:10</td>\n</tr>\n</tbody>\n</table></td>\n</tr></tbody></table>"
