      "passage": "<table><tbody><tr>\n<td></td>\n<td colspan=\"4\"><p>　　Answer the questions based on the poster\nbelow.</p>\n<table>\n<colgroup>\n<col>\n<col>\n<col>\n<col>\n</colgroup>\n<thead>\n<tr>\n<th colspan=\"4\"><blockquote>\n<p><strong>Dorothy Hodgkin:</strong> an outstanding chemist who won a\nNobel Prize in 1964 for her studies in vitamins.</p>\n</blockquote></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td colspan=\"4\"><blockquote>\n<p><strong>Grace Hopper:</strong> a mathematician who was a pioneer in\ndeveloping computer technology. She served in the U.S. Navy during World\nWar II.</p>\n</blockquote></td>\n</tr>\n<tr>\n<td colspan=\"4\"><blockquote>\n<p><strong>Maria Mayer:</strong> a scientist who won a Nobel Prize in\n1963 for her work in atomic science.</p>\n</blockquote></td>\n</tr>\n<tr>\n<td colspan=\"4\"><blockquote>\n<p><strong>Maria Mitchell:</strong> a famous astronomer who discovered a\nnew comet in 1847. She was the first woman ever to be voted into the\nAmerican Academy of Arts and Sciences.</p>\n</blockquote></td>\n</tr>\n<tr>\n<td colspan=\"4\"><blockquote>\n<p><strong>Nancy Roman:</strong> an astronomer who worked with rockets\nand space exploration. She was called a “wizard in math” while in\ncollege.</p>\n</blockquote></td>\n</tr>\n<tr>\n<td colspan=\"4\"><blockquote>\n<p><strong>Chien-Shiung Wu:</strong> a nuclear physicist who was\nregarded as the “top woman experimental physicist in the world” by\nPrinceton University in 1958. She came to the United States from\nChina.</p>\n</blockquote></td>\n</tr>\n<tr>\n<td><blockquote>\n<p><img src=\"img/114/source/image2.svg\" class=\"source-figure\"></p>\n</blockquote></td>\n<td><blockquote>\n<p><img src=\"img/114/source/image4.svg\" class=\"source-figure\"></p>\n</blockquote></td>\n<td><blockquote>\n<p><img src=\"img/114/source/image6.svg\" class=\"source-figure\"></p>\n</blockquote></td>\n<td><blockquote>\n<p><img src=\"img/114/source/image8.svg\" class=\"source-figure\"></p>\n</blockquote></td>\n</tr>\n</tbody>\n</table></td>\n</tr></tbody></table>"
